import{_ as i,o as t,c as r,ae as s}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Storage Layer — Ring Buffer and SQLite Persistence","description":"","frontmatter":{"work_package_id":"WP02","title":"Storage Layer — Ring Buffer and SQLite Persistence","lane":"done","dependencies":["WP01"],"base_branch":"024-audit-logging-and-session-replay-WP01","base_commit":"23250f22b35e5eea258e6fcd559f8bc87656ae52","created_at":"2026-03-01T13:32:18.537580+00:00","subtasks":["T005","T006","T007","T008"],"phase":"Phase 1 - Audit Foundation","assignee":"","agent":"claude-haiku","shell_pid":"66147","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/024-audit-logging-and-session-replay/tasks/WP02-ring-buffer-and-sqlite-storage.md","filePath":"specs/024-audit-logging-and-session-replay/tasks/WP02-ring-buffer-and-sqlite-storage.md"}'),l={name:"specs/024-audit-logging-and-session-replay/tasks/WP02-ring-buffer-and-sqlite-storage.md"};function a(o,e,n,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="work-package-prompt-wp02-storage-layer-—-ring-buffer-and-sqlite-persistence" tabindex="-1">Work Package Prompt: WP02 - Storage Layer — Ring Buffer and SQLite Persistence <a class="header-anchor" href="#work-package-prompt-wp02-storage-layer-—-ring-buffer-and-sqlite-persistence" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Storage Layer — Ring Buffer and SQLite Persistence&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement in-memory ring buffer for sub-millisecond reads on recent events.</li><li>Implement SQLite persistence for durable 30+ day retention.</li><li>Ensure ring buffer overflow spills to SQLite without event loss.</li><li>Validate zero event loss under crash scenarios.</li></ul><p>Success criteria:</p><ul><li>Ring buffer provides &lt; 1ms read access for recent events.</li><li>SQLite stores 30 days of events at 100k/day within 500 MB.</li><li>Overflow from ring buffer to SQLite loses zero events.</li><li>Simulated crash and restart recovers all persisted events.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/spec.md</code></li><li>WP01 output: AuditEvent schema, AuditSink interface.</li></ul><p>Constraints:</p><ul><li>Ring buffer capacity is configurable (default: 10,000 events).</li><li>SQLite must use WAL mode for concurrent reads/writes.</li><li>Writes never block reads.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t005-implement-in-memory-ring-buffer" tabindex="-1">Subtask T005 - Implement in-memory ring buffer <a class="header-anchor" href="#subtask-t005-implement-in-memory-ring-buffer" aria-label="Permalink to &quot;Subtask T005 - Implement in-memory ring buffer&quot;">​</a></h3><ul><li>Purpose: Provide fast read access to the most recent audit events for hot queries and real-time UI updates.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ring-buffer.ts</code>.</li><li>Implement <code>AuditRingBuffer</code> class with configurable capacity (default 10,000).</li><li>Use a fixed-size array with head/tail pointers for O(1) append and O(1) random access by index.</li><li>Implement <code>push(event: AuditEvent)</code>: append to buffer; if full, return the evicted event (oldest) for overflow handling.</li><li>Implement <code>getRecent(count: number): AuditEvent[]</code>: return the N most recent events.</li><li>Implement <code>query(filter: AuditFilter): AuditEvent[]</code>: filter events in the buffer by workspace, lane, session, actor, event type, time range.</li><li>Implement <code>getByCorrelationId(correlationId: string): AuditEvent[]</code>: return all events with the given correlation ID.</li><li>All read operations must complete in &lt; 1ms for a full 10,000-event buffer.</li><li>The buffer must be thread-safe if concurrent access is possible (Bun is single-threaded for JS, but verify).</li><li>Add capacity and current size metrics.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ring-buffer.ts</code></li></ul></li><li>Acceptance: <ul><li>O(1) append and eviction.</li><li>&lt; 1ms read for queries on full buffer.</li><li>Evicted events returned for overflow handling.</li><li>Metrics available.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t006-implement-sqlite-persistence-layer" tabindex="-1">Subtask T006 - Implement SQLite persistence layer <a class="header-anchor" href="#subtask-t006-implement-sqlite-persistence-layer" aria-label="Permalink to &quot;Subtask T006 - Implement SQLite persistence layer&quot;">​</a></h3><ul><li>Purpose: Provide durable, indexed storage for audit events supporting 30+ days of retention.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/sqlite-store.ts</code>.</li><li>Use <code>bun:sqlite</code> for the database connection.</li><li>Create table schema: <code>audit_events</code> with columns matching <code>AuditEvent</code> fields. Use <code>id</code> as primary key.</li><li>Create indexes on: <code>workspace_id</code>, <code>lane_id</code>, <code>session_id</code>, <code>actor</code>, <code>event_type</code>, <code>correlation_id</code>, <code>timestamp</code>.</li><li>Enable WAL mode for concurrent read/write access.</li><li>Implement <code>persist(events: AuditEvent[])</code>: batch insert events for efficiency.</li><li>Implement <code>query(filter: AuditFilter, options: { limit, offset }): AuditEvent[]</code>: indexed query with all filter dimensions.</li><li>Implement <code>getByCorrelationChain(correlationId: string): AuditEvent[]</code>: follow correlation ID chains.</li><li>Implement <code>count(filter?: AuditFilter): number</code>: count matching events.</li><li>Implement <code>getStorageSize(): number</code>: return SQLite file size in bytes.</li><li>Add database migration logic: create table and indexes on first run; versioned migrations for schema evolution.</li><li>Handle database corruption gracefully: detect, log critical error, attempt recovery.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/sqlite-store.ts</code></li></ul></li><li>Acceptance: <ul><li>Batch inserts are efficient (&gt; 1000 events/second).</li><li>Queries use indexes and return within 500ms for 1M events.</li><li>WAL mode enables concurrent reads/writes.</li><li>Storage size trackable.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-implement-ring-buffer-overflow-to-sqlite" tabindex="-1">Subtask T007 - Implement ring buffer overflow to SQLite <a class="header-anchor" href="#subtask-t007-implement-ring-buffer-overflow-to-sqlite" aria-label="Permalink to &quot;Subtask T007 - Implement ring buffer overflow to SQLite&quot;">​</a></h3><ul><li>Purpose: Ensure events evicted from the ring buffer are persisted to SQLite without loss.</li><li>Steps: <ol><li>Modify the <code>AuditSink</code> (from WP01) to use both the ring buffer and SQLite store.</li><li>On <code>write()</code>: a. Push the event to the ring buffer. b. If the ring buffer returns an evicted event, immediately persist it to SQLite. c. Periodically flush all ring buffer contents to SQLite (configurable interval, default 10 seconds).</li><li>On <code>flush()</code>: persist all current ring buffer events to SQLite.</li><li>Ensure the overflow path is atomic: either the event is in the ring buffer OR in SQLite, never lost between them.</li><li>Handle SQLite write failures during overflow: buffer overflow events in a secondary queue and retry.</li><li>Add overflow metrics: events overflowed, SQLite write failures, retry count.</li><li>Test: fill ring buffer to capacity + 100, verify all 100 overflow events are in SQLite.</li><li>Test: simulate SQLite failure during overflow, verify events are queued for retry.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/sink.ts</code> (integrate storage)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ring-buffer.ts</code> (overflow hook)</li></ul></li><li>Acceptance: <ul><li>Zero events lost during overflow.</li><li>SQLite failures handled with retry.</li><li>Periodic flush ensures durability.</li><li>Overflow metrics available.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-storage-chaos-tests" tabindex="-1">Subtask T008 - Storage chaos tests <a class="header-anchor" href="#subtask-t008-storage-chaos-tests" aria-label="Permalink to &quot;Subtask T008 - Storage chaos tests&quot;">​</a></h3><ul><li>Purpose: Validate zero event loss under crash and overflow scenarios using real SQLite operations.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/storage-chaos.test.ts</code>.</li><li>Test: write 50,000 events, flush, restart (simulate by creating new sink instance with same SQLite DB), verify all 50,000 events recoverable from SQLite.</li><li>Test: write events rapidly (1000/second), verify ring buffer overflow to SQLite loses zero events by comparing counts.</li><li>Test: simulate SQLite write failure (e.g., read-only filesystem mock), verify events are buffered and persisted on recovery.</li><li>Test: write events, simulate crash (SIGKILL-equivalent: abort without flush), restart, count events in SQLite, verify loss is bounded to unflushed ring buffer contents (acceptable loss documented).</li><li>Test: concurrent reads while writes are in progress (WAL mode), verify reads return consistent results.</li><li>Test: verify storage size is within 500 MB for 3 million events (30 days at 100k/day).</li><li>Use real SQLite (not mocked) for realistic chaos testing.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/storage-chaos.test.ts</code></li></ul></li><li>Acceptance: <ul><li>Zero event loss during normal overflow.</li><li>Bounded loss during hard crash documented.</li><li>Concurrent access works correctly.</li><li>Storage size within 500 MB target.</li></ul></li><li>Parallel: Yes (after T005-T007 are functional).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Chaos tests with real SQLite for crash and overflow scenarios.</li><li>Performance benchmarks for read/write latency.</li><li>Storage size validation at target event rates.</li><li>Concurrent access tests.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: SQLite WAL file grows large under sustained write pressure.</li><li>Mitigation: Periodic WAL checkpoint; monitor WAL size.</li><li>Risk: Hard crash loses unflushed ring buffer events.</li><li>Mitigation: Reduce flush interval; document acceptable loss window.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm ring buffer overflow spills to SQLite without loss.</li><li>Confirm WAL mode is enabled for concurrent access.</li><li>Confirm chaos tests use real SQLite.</li><li>Confirm storage size is within budget.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:32:19Z – claude-haiku – shell_pid=66147 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:34:26Z – claude-haiku – shell_pid=66147 – lane=done – Implemented: Ring buffer, SQLite storage with WAL, overflow handling, and chaos tests</li></ul>',28)])])}const h=i(l,[["render",a]]);export{p as __pageData,h as default};
